import{I as p,o as t,c as o,b6 as l,J as h,w as r,j as a,a as n}from"./chunks/framework.COUcLbTA.js";const k=JSON.parse('{"title":"The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법","description":"제로 베이스 독자를 위한 The Mom Test 입문 글입니다. 예의상 긍정 피드백을 피하고, 실제 행동, 구체적 사실, 이미 존재하는 문제를 중심으로 사용자 인터뷰를 진행해 \\"듣기에는 좋다\\"를 더 신뢰할 수 있는 수요 판단으로 바꾸는 법을 배웁니다.","frontmatter":{"title":"The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법","description":"제로 베이스 독자를 위한 The Mom Test 입문 글입니다. 예의상 긍정 피드백을 피하고, 실제 행동, 구체적 사실, 이미 존재하는 문제를 중심으로 사용자 인터뷰를 진행해 \\"듣기에는 좋다\\"를 더 신뢰할 수 있는 수요 판단으로 바꾸는 법을 배웁니다."},"headers":[],"relativePath":"ko-kr/stage-1/appendix-mom-test/index.md","filePath":"ko-kr/stage-1/appendix-mom-test/index.md"}'),d={name:"ko-kr/stage-1/appendix-mom-test/index.md"},m=Object.assign(d,{setup(c){const i="약 <strong>1.5시간</strong>";return(u,s)=>{const e=p("ChapterIntroduction");return t(),o("div",null,[s[1]||(s[1]=l('<h1 id="the-mom-test-사용자-인터뷰로-수요를-검증하는-방법" tabindex="-1">The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법 <a class="header-anchor" href="#the-mom-test-사용자-인터뷰로-수요를-검증하는-방법" aria-label="Permalink to “The Mom Test: 사용자 인터뷰로 수요를 검증하는 방법”">​</a></h1><p><a id="top-mom"></a></p><h2 id="본-장-안내" tabindex="-1">본 장 안내 <a class="header-anchor" href="#본-장-안내" aria-label="Permalink to “본 장 안내”">​</a></h2>',3)),h(e,{duration:i,tags:["사용자 인터뷰","수요 검증","사용자 리서치","제품 조사"],coreOutput:"진짜 정보를 더 잘 끌어내는 인터뷰 질문 묶음 1개",expectedOutput:"사용자의 예의상 격려를 검증으로 착각하지 않고, 실제 행동으로 방향을 판단할 수 있게 됨"},{default:r(()=>[...s[0]||(s[0]=[a("p",null,'많은 사람이 처음 제품 조사를 할 때 가장 중요한 것이 "사람을 찾아 이야기해 보는 것"이라고 생각합니다. 그래서 친구, 동료, 심지어 가족에게 묻습니다.',-1),a("ul",null,[a("li",null,"내 아이디어 어때?"),a("li",null,"이런 제품이 있으면 쓸 것 같아?"),a("li",null,"이 기능 괜찮아 보이지 않아?")],-1),a("p",null,"상대도 보통 매우 힘이 되는 피드백을 줍니다.",-1),a("ul",null,[a("li",null,"괜찮은데?"),a("li",null,"유용해 보인다"),a("li",null,"한번 해 봐도 좋을 것 같아")],-1),a("p",null,'문제는 이런 답변이 대개 판단에 도움이 되지 않는다는 점입니다. 그것들은 예의, 응원, 또는 그 자리에서 당신의 흥을 깨고 싶지 않은 자연스러운 반응에 더 가깝습니다. 당신은 "시장 검증"을 얻었다고 생각하지만, 사실은 의사결정에 쓰기 어려운 위로만 잔뜩 모은 것일 수 있습니다.',-1),a("p",null,[n("The Mom Test 방법은 바로 이 문제를 해결하기 위해 만들어졌습니다. 이 방법은 우리에게 이렇게 상기시킵니다. "),a("strong",null,"사용자가 일부러 당신을 속이는 것이 아니라, 당신의 질문 방식이 상대를 듣기 좋지만 쓸모없는 답으로 자연스럽게 이끈다"),n("는 것입니다.")],-1)])]),_:1}),s[2]||(s[2]=l(`<div class="info custom-block"><p class="custom-block-title">최소 SOP</p><p><strong>목적</strong>: 읽고 나면 사용자와 어떻게 이야기해야 &quot;듣기 좋다&quot;만 듣지 않고, 방향 판단에 도움이 되는 정보를 실제로 물어낼 수 있는지 더 명확해집니다.</p><p><strong>행동 항목</strong>: 원래 물어보려던 질문 5개를 바꾸고, 우선 &quot;최근 한 번은 언제였나요&quot;, &quot;그때 어떻게 처리했나요&quot;를 묻습니다.</p><p><strong>결과</strong>: 무엇이 의견이고, 무엇이 판단을 뒷받침하는 증거인지 더 쉽게 구분할 수 있습니다.</p><p><strong>키워드 이동</strong>: <a href="#mom-what">The Mom Test란 무엇인가</a> · <a href="#mom-principles">세 가지 핵심 원칙</a> · <a href="#mom-ai">AI는 어떻게 도와줄 수 있나</a></p></div><h2 id="다음-내용을-배우게-됩니다" tabindex="-1">다음 내용을 배우게 됩니다 <a class="header-anchor" href="#다음-내용을-배우게-됩니다" aria-label="Permalink to “다음 내용을 배우게 됩니다”">​</a></h2><ol><li>The Mom Test가 정확히 어떤 문제를 해결하는지, 왜 많은 &quot;사용자 조사&quot;가 실제 정보를 조사하지 못하는지</li><li>이 방법의 핵심 원칙: 의견은 적게 묻고 행동을 더 묻기, 가정보다는 사실을 더 묻기</li><li>거짓 양성 피드백을 쉽게 얻는 질문을 더 가치 있는 인터뷰 질문으로 바꾸는 법</li><li>The Mom Test를 JTBD, 수요 검증, MVP 판단과 연결해 사용하는 법</li></ol><p><a id="mom-what"></a></p><h2 id="_1-the-mom-test란-정확히-무엇인가" tabindex="-1"><a href="#top-mom">1. The Mom Test란 정확히 무엇인가</a> <a class="header-anchor" href="#_1-the-mom-test란-정확히-무엇인가" aria-label="Permalink to “1. The Mom Test란 정확히 무엇인가”">​</a></h2><p>The Mom Test는 Rob Fitzpatrick의 동명 책에서 나온 방법입니다. 이름은 농담처럼 들리지만 핵심을 아주 정확히 찌릅니다.</p><p><strong>당신의 엄마조차도 &quot;이건 별로인 아이디어야&quot;라고 직접 말하기는 어렵습니다.</strong></p><p>그 이유는 엄마가 정직하지 않아서가 아닙니다.</p><ul><li>당신을 상처 입히고 싶지 않습니다.</li><li>무의식적으로 당신을 격려합니다.</li><li>당신의 표현 방식에 맞춰 쉽게 대답합니다.</li></ul><p>사실 엄마뿐 아니라 친구, 동료, 예전 동창, 심지어 많은 낯선 사람도 당신의 제품 아이디어를 마주하면 비슷한 &quot;긍정 피드백&quot;을 주는 경우가 많습니다. 이것은 수요가 진짜 있다는 뜻이 아니라, 질문을 듣기 좋은 답이 나오기 쉬운 형태로 했다는 뜻입니다.</p><p>그래서 The Mom Test의 핵심은 &quot;엄마에게 묻지 마라&quot;가 아닙니다.</p><p><strong>누구라도 당신에게 맞장구치게 만드는 형태로 질문하지 말라는 것입니다.</strong></p><p>이 방법이 진짜로 가르치려는 것은 대화를 통해 실제 수요에 더 가까운 정보를 얻는 법이지, 스스로 기분 좋아지는 댓글을 잔뜩 모으는 법이 아닙니다.</p><h2 id="_2-해결하는-핵심-문제는-무엇인가" tabindex="-1">2. 해결하는 핵심 문제는 무엇인가 <a class="header-anchor" href="#_2-해결하는-핵심-문제는-무엇인가" aria-label="Permalink to “2. 해결하는 핵심 문제는 무엇인가”">​</a></h2><p>The Mom Test가 주로 해결하는 것은 매우 흔한 인지 착각입니다.</p><p><strong>예의상 긍정 피드백을 실제 수요로 착각하는 것</strong>입니다.</p><p>예를 들어 이렇게 묻는다고 해 봅시다.</p><ul><li>이 App 아이디어 어때요?</li><li>AI가 이력서를 써 주는 도구를 만들면 쓸 것 같아요?</li><li>이 기능은 가치 있어 보이나요?</li></ul><p>이 질문들의 공통점은 다음입니다.</p><ul><li>모두 &quot;의견&quot;을 묻는다.</li><li>모두 약간의 암시를 담고 있다.</li><li>모두 아직 일어나지 않은 미래를 이야기한다.</li></ul><p>사람이 &quot;의견&quot;과 &quot;미래 가정&quot;에 답할 때는 보통 안정적이지 않습니다. 많은 사람은 자신의 흥미, 실행력, 미래 구매 의사를 과대평가합니다.</p><p>그래서 The Mom Test는 이렇게 알려 줍니다.</p><ul><li>다른 사람이 내 아이디어를 어떻게 평가하는지 너무 믿지 마세요.</li><li>다른 사람이 미래 행동을 어떻게 예측하는지 너무 믿지 마세요.</li><li>가능한 한 이미 일어난 사용자의 실제 행동으로 돌아가세요.</li></ul><p>&quot;쓸 것 같나요?&quot;보다 &quot;지난번에 이 일을 어떻게 처리했나요?&quot;가 대개 진실에 더 가깝기 때문입니다.</p><p><a id="mom-principles"></a></p><h2 id="_3-세-가지-핵심-원칙" tabindex="-1"><a href="#top-mom">3. 세 가지 핵심 원칙</a> <a class="header-anchor" href="#_3-세-가지-핵심-원칙" aria-label="Permalink to “3. 세 가지 핵심 원칙”">​</a></h2><p>가장 중요한 부분만 먼저 기억하고 싶다면 아래 세 가지 원칙을 기억하세요.</p><h3 id="_3-1-내-아이디어는-적게-말하고-사용자의-과거-실제-경험을-더-이야기하게-하기" tabindex="-1">3.1 내 아이디어는 적게 말하고, 사용자의 과거 실제 경험을 더 이야기하게 하기 <a class="header-anchor" href="#_3-1-내-아이디어는-적게-말하고-사용자의-과거-실제-경험을-더-이야기하게-하기" aria-label="Permalink to “3.1 내 아이디어는 적게 말하고, 사용자의 과거 실제 경험을 더 이야기하게 하기”">​</a></h3><p>많은 무효 인터뷰는 시작하자마자 자기 솔루션을 설명하고, 자신이 얼마나 신났는지 말하고, 어떤 제품을 만들 준비인지 이야기합니다. 문제는 당신이 너무 많이 말하는 순간, 상대가 &quot;맞춰 주기&quot;, &quot;격려하기&quot; 모드로 바뀌기 쉽다는 점입니다.</p><p>반대로 더 좋은 방식은 상대의 경험에 초점을 두는 것입니다.</p><ul><li>최근에 이 문제를 만난 것은 언제였나요?</li><li>그때 무엇을 하고 있었나요?</li><li>결국 어떻게 처리했나요?</li><li>어느 단계가 가장 번거로웠나요?</li></ul><p>이런 질문은 대화를 상상 속 선호가 아니라 현실로 더 자연스럽게 되돌립니다.</p><h3 id="_3-2-추상적-의견은-적게-묻고-구체적-사실을-더-묻기" tabindex="-1">3.2 추상적 의견은 적게 묻고, 구체적 사실을 더 묻기 <a class="header-anchor" href="#_3-2-추상적-의견은-적게-묻고-구체적-사실을-더-묻기" aria-label="Permalink to “3.2 추상적 의견은 적게 묻고, 구체적 사실을 더 묻기”">​</a></h3><p>&quot;이 기능 괜찮은 것 같아요&quot;, &quot;듣기에는 좋아요&quot;, &quot;조금 쓸모 있어 보이네요&quot; 같은 표현은 너무 추상적이라 제품 의사결정에 쓰기 어렵습니다.</p><p>더 가치 있는 정보는 보통 이런 모습입니다.</p><ul><li>지난주에 이 일 때문에 2시간을 썼어요.</li><li>지금은 Excel과 WeChat으로 버티고 있어요.</li><li>지난달 이미 비슷한 도구에 돈을 낸 적이 있어요.</li><li>제가 가장 두려운 건 느린 것이 아니라 잘못하는 거예요.</li></ul><p>이런 정보가 문제 강도, 빈도, 지불 가능성을 판단하는 데 진짜 도움이 됩니다.</p><h3 id="_3-3-사용자가-원하는-솔루션을-적게-묻고-지금-어떻게-해결하는지-더-보기" tabindex="-1">3.3 사용자가 원하는 솔루션을 적게 묻고, 지금 어떻게 해결하는지 더 보기 <a class="header-anchor" href="#_3-3-사용자가-원하는-솔루션을-적게-묻고-지금-어떻게-해결하는지-더-보기" aria-label="Permalink to “3.3 사용자가 원하는 솔루션을 적게 묻고, 지금 어떻게 해결하는지 더 보기”">​</a></h3><p>사용자는 자신의 어려움을 설명하는 데는 능숙하지만, 해결책을 설계하는 데 항상 능숙하지는 않습니다.</p><p>이렇게 묻는다면:</p><ul><li>AI가 자동으로 이걸 해 주면 좋겠어요?</li><li>지능형 기능을 넣으면 도움이 될까요?</li></ul><p>대개 얻는 것은 어떤 솔루션에 대한 흐릿한 태도일 뿐, 수요 자체가 아닙니다.</p><p>더 좋은 질문은 다음입니다.</p><ul><li>지금 이 문제를 어떤 방법으로 처리하나요?</li><li>왜 그 방법을 선택했나요?</li><li>그 방법은 어디가 충분하지 않나요?</li></ul><p>기존 대체 방안을 명확히 보는 것은 &quot;무엇을 원하세요?&quot;라고 직접 묻는 것보다 훨씬 중요합니다.</p><h2 id="_4-왜-사람들은-늘-듣기-좋지만-쓸모없는-답을-줄까" tabindex="-1">4. 왜 사람들은 늘 듣기 좋지만 쓸모없는 답을 줄까 <a class="header-anchor" href="#_4-왜-사람들은-늘-듣기-좋지만-쓸모없는-답을-줄까" aria-label="Permalink to “4. 왜 사람들은 늘 듣기 좋지만 쓸모없는 답을 줄까”">​</a></h2><p>이 점을 이해하면 인터뷰에서 오판이 훨씬 줄어듭니다.</p><h3 id="_4-1-사람은-무의식적으로-예의를-지킨다" tabindex="-1">4.1 사람은 무의식적으로 예의를 지킨다 <a class="header-anchor" href="#_4-1-사람은-무의식적으로-예의를-지킨다" aria-label="Permalink to “4.1 사람은 무의식적으로 예의를 지킨다”">​</a></h3><p>특히 대화 상대와 관계가 있을 때, 상대는 직접 이렇게 말하기 어렵습니다.</p><ul><li>이 방향은 별로인 것 같아요.</li><li>저는 절대 안 쓸 것 같아요.</li><li>이 문제는 제게 그렇게 중요하지 않아요.</li></ul><p>대신 &quot;괜찮은데&quot;, &quot;기회가 있으면 해 봐도 좋겠다&quot;라고 말할 가능성이 큽니다.</p><h3 id="_4-2-사람은-미래의-자신을-과대평가한다" tabindex="-1">4.2 사람은 미래의 자신을 과대평가한다 <a class="header-anchor" href="#_4-2-사람은-미래의-자신을-과대평가한다" aria-label="Permalink to “4.2 사람은 미래의 자신을 과대평가한다”">​</a></h3><p>많은 사람은 자신이 미래에 진심으로 이렇게 될 것이라 믿습니다.</p><ul><li>더 자율적일 것이다.</li><li>더 열심히 배울 것이다.</li><li>더 기꺼이 돈을 낼 것이다.</li><li>새 도구를 더 기꺼이 시도할 것이다.</li></ul><p>그래서 &quot;있으면 아마 쓸 것 같아요&quot;는 종종 미래에 정말 쓴다는 뜻이 아닙니다.</p><h3 id="_4-3-질문-방식-자체가-답을-유도한다" tabindex="-1">4.3 질문 방식 자체가 답을 유도한다 <a class="header-anchor" href="#_4-3-질문-방식-자체가-답을-유도한다" aria-label="Permalink to “4.3 질문 방식 자체가 답을 유도한다”">​</a></h3><p>이렇게 물을 때:</p><ul><li>내 아이디어 괜찮지 않아?</li><li>이 기능이 당신에게 도움이 되지 않을까?</li></ul><p>사실 질문 안에 이미 &quot;정답&quot;을 몰래 넣은 것입니다.</p><p>그래서 The Mom Test는 특히 강조합니다. <strong>인터뷰를 인정을 구하는 자리로 만들지 마세요.</strong></p><h2 id="_5-직접-비교-어떤-질문은-망하기-쉽고-어떤-질문은-더-가치-있는가" tabindex="-1">5. 직접 비교: 어떤 질문은 망하기 쉽고, 어떤 질문은 더 가치 있는가 <a class="header-anchor" href="#_5-직접-비교-어떤-질문은-망하기-쉽고-어떤-질문은-더-가치-있는가" aria-label="Permalink to “5. 직접 비교: 어떤 질문은 망하기 쉽고, 어떤 질문은 더 가치 있는가”">​</a></h2><p>아래 비교는 거의 모든 초보자가 바로 써먹을 수 있습니다.</p><table tabindex="0"><thead><tr><th>망하기 쉬운 질문</th><th>더 가치 있는 질문</th></tr></thead><tbody><tr><td>내 아이디어 어때요?</td><td>최근에 이 문제를 만난 것은 언제였나요?</td></tr><tr><td>이런 제품이 있으면 쓸 건가요?</td><td>지금은 이 일을 어떻게 처리하고 있나요?</td></tr><tr><td>이 기능에 돈을 낼 의향이 있나요?</td><td>지난번 이 문제 때문에 돈을 쓴 적이 있나요? 무엇에 썼나요?</td></tr><tr><td>이 기능이 중요하다고 생각하나요?</td><td>이 흐름에서 가장 짜증 나고, 느리고, 불안한 단계는 무엇인가요?</td></tr><tr><td>AI가 자동으로 도와주면 좋겠나요?</td><td>지금 더 편한 해결책을 아직 찾지 못한 이유는 무엇인가요?</td></tr></tbody></table><p>이 표에서 가장 중요한 것은 구체적인 문장이 아니라 그 뒤의 방향입니다.</p><ul><li>의견에서 사실로</li><li>미래에서 과거로</li><li>당신의 솔루션에서 사용자의 문제로</li></ul><h2 id="_6-제로-베이스도-바로-사용할-수-있는-인터뷰-리듬" tabindex="-1">6. 제로 베이스도 바로 사용할 수 있는 인터뷰 리듬 <a class="header-anchor" href="#_6-제로-베이스도-바로-사용할-수-있는-인터뷰-리듬" aria-label="Permalink to “6. 제로 베이스도 바로 사용할 수 있는 인터뷰 리듬”">​</a></h2><p>지금 바로 사람을 찾아 이야기하고 싶다면 아래 순서를 그대로 따라도 됩니다.</p><h3 id="_6-1-시작-내가-배우는-중이지-팔려고-온-것이-아니라고-설명하기" tabindex="-1">6.1 시작: 내가 배우는 중이지 팔려고 온 것이 아니라고 설명하기 <a class="header-anchor" href="#_6-1-시작-내가-배우는-중이지-팔려고-온-것이-아니라고-설명하기" aria-label="Permalink to “6.1 시작: 내가 배우는 중이지 팔려고 온 것이 아니라고 설명하기”">​</a></h3><p>예를 들면:</p><blockquote><p>요즘 사람들이 이 문제를 어떻게 처리하는지 조사하고 있어요. 먼저 실제 상황을 이해하려는 것이지, 뭔가를 팔러 온 것은 아닙니다.</p></blockquote><p>이 표현은 상대가 &quot;긍정 피드백을 줘야 한다&quot;는 심리적 부담을 내려놓기 쉽게 합니다.</p><h3 id="_6-2-최근의-실제-경험부터-묻기" tabindex="-1">6.2 최근의 실제 경험부터 묻기 <a class="header-anchor" href="#_6-2-최근의-실제-경험부터-묻기" aria-label="Permalink to “6.2 최근의 실제 경험부터 묻기”">​</a></h3><p>아래 질문으로 시작할 수 있습니다.</p><ul><li>최근에 이 문제를 만난 것은 언제였나요?</li><li>그때 정확히 무슨 일이 있었나요?</li><li>처음에는 어떻게 처리하려 했나요?</li></ul><p>대화가 구체적인 사건으로 들어가면 정보 품질은 보통 뚜렷하게 올라갑니다.</p><h3 id="_6-3-행동-비용-대체-방안을-계속-캐묻기" tabindex="-1">6.3 행동, 비용, 대체 방안을 계속 캐묻기 <a class="header-anchor" href="#_6-3-행동-비용-대체-방안을-계속-캐묻기" aria-label="Permalink to “6.3 행동, 비용, 대체 방안을 계속 캐묻기”">​</a></h3><p>이어서 묻습니다.</p><ul><li>지금은 어떤 방법으로 해결하나요?</li><li>그 방법에서 가장 불편한 점은 무엇인가요?</li><li>이 일 때문에 시간, 돈, 에너지를 얼마나 썼나요?</li><li>다른 방법도 시도해 봤나요? 왜 계속 쓰지 않았나요?</li></ul><h3 id="_6-4-마지막에-고통감과-우선순위-판단하기" tabindex="-1">6.4 마지막에 고통감과 우선순위 판단하기 <a class="header-anchor" href="#_6-4-마지막에-고통감과-우선순위-판단하기" aria-label="Permalink to “6.4 마지막에 고통감과 우선순위 판단하기”">​</a></h3><p>&quot;아픈가요?&quot;라고 직접 묻지 않아도 됩니다. 세부 정보에서 판단할 수 있습니다.</p><ul><li>자주 만나는 문제인가</li><li>이미 적극적으로 보완하고 있는가</li><li>이미 비용을 지불할 의향을 보였는가</li><li>말할 때 뚜렷한 감정이 실려 있는가</li></ul><p>이것들이 &quot;이게 당신의 고통점인가요?&quot;라는 한 문장보다 훨씬 유용합니다.</p><h2 id="_7-더-완전한-예시" tabindex="-1">7. 더 완전한 예시 <a class="header-anchor" href="#_7-더-완전한-예시" aria-label="Permalink to “7. 더 완전한 예시”">​</a></h2><p>&quot;AI가 대학생 이력서 수정을 돕는&quot; 제품을 만들고 싶다고 가정해 봅시다.</p><h3 id="잘못된-질문-방식" tabindex="-1">잘못된 질문 방식 <a class="header-anchor" href="#잘못된-질문-방식" aria-label="Permalink to “잘못된 질문 방식”">​</a></h3><p>동급생에게 이렇게 묻습니다.</p><blockquote><p>AI 이력서 최적화 도구를 만들고 싶은데, 어때?<br> 직무에 따라 이력서를 자동으로 고쳐 준다면 쓸 것 같아?</p></blockquote><p>이때 상대는 이렇게 말할 가능성이 큽니다.</p><ul><li>괜찮아 보여</li><li>유용할 것 같아</li><li>무료면 한번 써 볼게</li></ul><p>이 답변으로는 수요가 얼마나 강한지 거의 판단할 수 없습니다.</p><h3 id="더-좋은-질문-방식" tabindex="-1">더 좋은 질문 방식 <a class="header-anchor" href="#더-좋은-질문-방식" aria-label="Permalink to “더 좋은 질문 방식”">​</a></h3><p>이렇게 바꿔 물을 수 있습니다.</p><blockquote><p>최근에 이력서를 고친 것은 언제였나요?<br> 그때 왜 고쳐야 했나요?<br> 어떻게 고쳤나요?<br> 어느 단계가 가장 막혔나요?<br> 다른 사람에게 봐 달라고 한 적이 있나요?<br> 이력서 때문에 돈을 쓰거나 많은 시간을 쓴 적이 있나요?</p></blockquote><p>이 질문을 통해 다음 정보를 얻을 수 있습니다.</p><ul><li>많은 사람은 못 쓰는 것이 아니라 직무별로 어떻게 고쳐야 할지 모른다.</li><li>가장 아픈 것은 레이아웃이 아니라 &quot;어떤 경험을 써야 할지 모르겠다&quot;이다.</li><li>그들이 미루는 것은 게으름 때문이 아니라 매번 이력서 수정이 매우 소모적이기 때문이다.</li><li>그들은 이미 선배 조언, 템플릿 사이트, AI 도구, 친구에게 부탁하기로 겨우 해결하고 있다.</li></ul><p>이제 실제 문제에 훨씬 가까워졌습니다.</p><h2 id="_8-the-mom-test와-jtbd는-어떻게-함께-쓰는가" tabindex="-1">8. The Mom Test와 JTBD는 어떻게 함께 쓰는가 <a class="header-anchor" href="#_8-the-mom-test와-jtbd는-어떻게-함께-쓰는가" aria-label="Permalink to “8. The Mom Test와 JTBD는 어떻게 함께 쓰는가”">​</a></h2><p>JTBD가 &quot;사용자가 어떤 진전을 이루고 싶어 하는지&quot;를 보게 해 준다면, The Mom Test는 이렇게 가르쳐 주는 것에 가깝습니다.</p><p><strong>인터뷰를 통해 이 job이 정말 존재하는지 확인하는 방법</strong>입니다.</p><p>둘은 완전히 이어서 쓸 수 있습니다.</p><ol><li>먼저 JTBD로 하나의 job을 가정한다.</li><li>The Mom Test 방식으로 사용자에게 최근의 실제 경험을 묻는다.</li><li>이 job이 정말 자주 발생하고, 실제이며, 우선 만들 가치가 있는지 본다.</li></ol><p>예를 들어 JTBD 가설이 다음과 같다고 합시다.</p><blockquote><p>인턴십에 지원하려고 할 때, 나는 예전 이력서를 빠르게 직무에 맞는 버전으로 바꾸고 싶다. 그래야 가능한 한 빨리 지원을 완료할 수 있다.</p></blockquote><p>그러면 The Mom Test 스타일 질문으로 검증할 수 있습니다.</p><ul><li>최근에 지원한 것은 언제였나요?</li><li>그때 이력서는 어떻게 고쳤나요?</li><li>어느 문단이 가장 쓰기 어려웠나요?</li><li>다 고친 뒤 충분히 좋은지 어떻게 판단했나요?</li></ul><p>이렇게 방법이 연결됩니다.</p><ul><li>JTBD는 수요 가설을 정의하게 도와줍니다.</li><li>The Mom Test는 인터뷰로 가설을 검증하게 도와줍니다.</li></ul><h2 id="_9-초보자가-사용자-인터뷰에서-가장-흔히-하는-오해" tabindex="-1">9. 초보자가 사용자 인터뷰에서 가장 흔히 하는 오해 <a class="header-anchor" href="#_9-초보자가-사용자-인터뷰에서-가장-흔히-하는-오해" aria-label="Permalink to “9. 초보자가 사용자 인터뷰에서 가장 흔히 하는 오해”">​</a></h2><h3 id="_9-1-인터뷰를-제품-설명회로-만들기" tabindex="-1">9.1 인터뷰를 제품 설명회로 만들기 <a class="header-anchor" href="#_9-1-인터뷰를-제품-설명회로-만들기" aria-label="Permalink to “9.1 인터뷰를 제품 설명회로 만들기”">​</a></h3><p>자신의 생각을 너무 많이 말하면 상대는 진짜 상황을 말하기보다 당신에게 맞춰 주기 쉽습니다.</p><h3 id="_9-2-인터뷰-대상이-전부-지인" tabindex="-1">9.2 인터뷰 대상이 전부 지인 <a class="header-anchor" href="#_9-2-인터뷰-대상이-전부-지인" aria-label="Permalink to “9.2 인터뷰 대상이 전부 지인”">​</a></h3><p>지인과 이야기하면 안 되는 것은 아니지만, 지인은 당신을 격려하기 더 쉽습니다. 당신을 지지하는 사람만 찾지 말고, 실제 사용자에 더 가까운 사람을 섞어야 합니다.</p><h3 id="_9-3-너무-일찍-기능을-추궁하기" tabindex="-1">9.3 너무 일찍 기능을 추궁하기 <a class="header-anchor" href="#_9-3-너무-일찍-기능을-추궁하기" aria-label="Permalink to “9.3 너무 일찍 기능을 추궁하기”">​</a></h3><p>문제를 아직 명확히 하지 못했는데 버튼, 인터페이스, 기능 세부사항을 묻기 시작하면 보통 너무 일찍 해결책으로 들어가는 것입니다.</p><h3 id="_9-4-쓸-것-같다-한마디를-검증-결과로-여기기" tabindex="-1">9.4 &quot;쓸 것 같다&quot; 한마디를 검증 결과로 여기기 <a class="header-anchor" href="#_9-4-쓸-것-같다-한마디를-검증-결과로-여기기" aria-label="Permalink to “9.4 &quot;쓸 것 같다&quot; 한마디를 검증 결과로 여기기”">​</a></h3><p>인터뷰는 방향 판단을 도울 뿐, 검증이 완료됐다는 뜻은 아닙니다. 진짜 검증은 결국 사용자가 시간, 전환 비용, 시험 사용 행동, 심지어 지불처럼 실제 비용을 낼 의향이 있는지 봐야 합니다.</p><h3 id="_9-5-인터뷰-후-정리하지-않기" tabindex="-1">9.5 인터뷰 후 정리하지 않기 <a class="header-anchor" href="#_9-5-인터뷰-후-정리하지-않기" aria-label="Permalink to “9.5 인터뷰 후 정리하지 않기”">​</a></h3><p>이야기하고 그냥 두면 정보는 금방 흐릿한 인상으로 변합니다. 가능한 한 빨리 정리하는 것이 좋습니다.</p><ul><li>자주 나타나는 문제</li><li>사용자 원문 속 감정 단어</li><li>현재 대체 방안</li><li>이미 지불한 비용</li><li>자신의 새로운 판단</li></ul><h2 id="_10-바로-복사해-쓸-수-있는-질문-목록" tabindex="-1">10. 바로 복사해 쓸 수 있는 질문 목록 <a class="header-anchor" href="#_10-바로-복사해-쓸-수-있는-질문-목록" aria-label="Permalink to “10. 바로 복사해 쓸 수 있는 질문 목록”">​</a></h2><p>빨리 시작하고 싶다면 충분히 범용적인 질문 묶음이 여기 있습니다.</p><h3 id="시작-질문" tabindex="-1">시작 질문 <a class="header-anchor" href="#시작-질문" aria-label="Permalink to “시작 질문”">​</a></h3><ul><li>최근에 이 문제를 만난 것은 언제였나요?</li><li>그때 구체적으로 무슨 일이 있었나요?</li></ul><h3 id="행동-질문" tabindex="-1">행동 질문 <a class="header-anchor" href="#행동-질문" aria-label="Permalink to “행동 질문”">​</a></h3><ul><li>그때 어떻게 처리했나요?</li><li>왜 그 방법을 선택했나요?</li></ul><h3 id="비용-질문" tabindex="-1">비용 질문 <a class="header-anchor" href="#비용-질문" aria-label="Permalink to “비용 질문”">​</a></h3><ul><li>이 일은 보통 시간이나 에너지를 얼마나 쓰게 하나요?</li><li>이 문제를 해결하려고 돈을 쓴 적이 있나요?</li></ul><h3 id="대체-방안-질문" tabindex="-1">대체 방안 질문 <a class="header-anchor" href="#대체-방안-질문" aria-label="Permalink to “대체 방안 질문”">​</a></h3><ul><li>다른 도구나 방법을 시도해 본 적이 있나요?</li><li>왜 결국 계속 쓰지 않았나요?</li></ul><h3 id="마무리-질문" tabindex="-1">마무리 질문 <a class="header-anchor" href="#마무리-질문" aria-label="Permalink to “마무리 질문”">​</a></h3><ul><li>앞으로 같은 문제를 다시 만난다면, 가장 이상적인 해결 방식은 어떤 모습이어야 할까요?</li></ul><p>주의하세요. 이 마무리 질문은 물어봐도 되지만, 가장 뒤에 두는 것이 좋습니다. 앞에서는 바람이 아니라 사실을 얻는 것이 더 중요하기 때문입니다.</p><h2 id="_11-정리" tabindex="-1">11. 정리 <a class="header-anchor" href="#_11-정리" aria-label="Permalink to “11. 정리”">​</a></h2><p>The Mom Test의 가장 중요한 기여는 &quot;대화를 더 잘하는&quot; 기술을 주는 것이 아니라, 더 맑은 판단 방식을 세워 주는 것입니다.</p><ul><li>다른 사람이 내 아이디어를 칭찬하는 말을 너무 빨리 믿지 마세요.</li><li>&quot;있으면 쓸 것 같아요&quot;를 실제 수요로 여기지 마세요.</li><li>인터뷰가 인정을 구하는 자리가 되게 하지 마세요.</li></ul><p>진짜 가치 있는 인터뷰는 가능한 한 다음으로 돌아가야 합니다.</p><ul><li>사용자의 최근 실제 경험</li><li>지금은 어떻게 처리하고 있는가</li><li>이미 어떤 비용을 치렀는가</li><li>어디에서 분명히 불편함을 느끼는가</li></ul><p>이렇게 묻기 시작하면 얻는 정보가 때로는 그렇게 듣기 좋지 않을 수 있지만, 보통 훨씬 더 유용합니다.<br> 제품을 만들 때는 <strong>쓸모 있는 진실이 듣기 좋은 격려보다 언제나 더 중요합니다.</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-ai로-사용자-인터뷰를-돕는-방법" tabindex="-1"><a href="#top-mom">12. AI로 사용자 인터뷰를 돕는 방법</a> <a class="header-anchor" href="#_12-ai로-사용자-인터뷰를-돕는-방법" aria-label="Permalink to “12. AI로 사용자 인터뷰를 돕는 방법”">​</a></h2><p>The Mom Test는 본질적으로 &quot;진짜 사람과 이야기하는&quot; 방법이므로 AI가 실제 인터뷰를 대체할 수는 없습니다. 하지만 AI는 인터뷰 전, 중, 후에 보조 역할을 하기에 매우 적합하며, 특히 초보자의 진입 장벽을 낮추는 데 좋습니다.</p><h3 id="_12-1-ai에게-망하기-쉬운-질문-을-고쳐-쓰게-하기" tabindex="-1">12.1 AI에게 &quot;망하기 쉬운 질문&quot;을 고쳐 쓰게 하기 <a class="header-anchor" href="#_12-1-ai에게-망하기-쉬운-질문-을-고쳐-쓰게-하기" aria-label="Permalink to “12.1 AI에게 &quot;망하기 쉬운 질문&quot;을 고쳐 쓰게 하기”">​</a></h3><p>많은 사람이 &quot;내 아이디어 어때요&quot;라고 물어보면 안 된다는 것을 알지만, 막상 입을 열면 다시 그런 문장으로 돌아갑니다. 준비한 질문을 AI에게 주고 고쳐 쓰게 할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>아래는 사용자 인터뷰에서 묻고 싶은 질문들이야.</span></span>
<span class="line"><span>[질문 붙여넣기]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The Mom Test 원칙으로 고쳐 써 줘.</span></span>
<span class="line"><span>1. 의견형 질문 삭제</span></span>
<span class="line"><span>2. 미래 가정 질문 삭제</span></span>
<span class="line"><span>3. 가능한 한 과거 실제 행동, 기존 대체 방안, 이미 지불한 비용을 중심으로 바꾸기</span></span>
<span class="line"><span>4. 마지막에 바로 인터뷰할 수 있는 질문 8~10개 목록으로 정리</span></span></code></pre></div><p>아주 초보적인 입력도 괜찮습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>사용자에게 이렇게 묻고 싶어.</span></span>
<span class="line"><span>1. AI 이력서 수정 도구를 만들면 어때요?</span></span>
<span class="line"><span>2. 쓸 것 같나요?</span></span>
<span class="line"><span>3. 돈을 낼 의향이 있나요?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>더 좋은 질문으로 바꿔 줘.</span></span></code></pre></div><p>AI가 주는 유용한 출력은 이런 모습일 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>고친 질문:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 최근에 이력서를 고친 것은 언제였나요?</span></span>
<span class="line"><span>2. 그때 왜 고쳐야 했나요?</span></span>
<span class="line"><span>3. 어떻게 고쳤나요?</span></span>
<span class="line"><span>4. 어느 단계가 가장 시간이 많이 걸렸나요?</span></span>
<span class="line"><span>5. 다른 사람에게 봐 달라고 한 적이 있나요?</span></span>
<span class="line"><span>6. 이전에 이력서 수정에 돈을 쓰거나 많은 시간을 쓴 적이 있나요?</span></span></code></pre></div><p>이 출력은 매우 도움이 됩니다. 원래 &quot;의견을 묻는&quot; 질문을 바로 &quot;실제 행동을 묻는&quot; 질문으로 바꿔 주기 때문입니다.</p><h3 id="_12-2-ai에게-대상별-인터뷰-개요를-만들게-하기" tabindex="-1">12.2 AI에게 대상별 인터뷰 개요를 만들게 하기 <a class="header-anchor" href="#_12-2-ai에게-대상별-인터뷰-개요를-만들게-하기" aria-label="Permalink to “12.2 AI에게 대상별 인터뷰 개요를 만들게 하기”">​</a></h3><p>같은 방향이라도 사람군이 다르면 인터뷰의 중점은 달라집니다. 예를 들어 학생, HR, 프리랜서는 관심사가 완전히 다릅니다. AI에게 서로 다른 대상별로 개요를 만들게 할 수 있습니다.</p><ul><li>초보 사용자 대상: 최근 한 번의 실제 경험을 중점적으로 이해</li><li>헤비 사용자 대상: 대체 방안과 고통감을 중점적으로 이해</li><li>유료 사용자 대상: 이미 비용을 지불했는지 중점적으로 이해</li></ul><p>이렇게 하면 실제 대화할 때 리듬이 생기고, 모든 사람에게 똑같은 질문만 던지지 않게 됩니다.</p><p>예를 들어 이렇게 바로 입력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>두 유형의 사람과 이야기하려고 해.</span></span>
<span class="line"><span>1. 처음 인턴십을 찾는 대학생</span></span>
<span class="line"><span>2. 이미 다른 사람의 이력서를 많이 봐 준 선배</span></span>
<span class="line"><span></span></span>
<span class="line"><span>각각 인터뷰 개요를 만들어 줘. 각 개요는 질문 6개로 해 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>대학생 대상:</span></span>
<span class="line"><span>1. 최근에 인턴십에 지원한 것은 언제였나요?</span></span>
<span class="line"><span>2. 그때 가장 막힌 단계는 무엇이었나요?</span></span>
<span class="line"><span>3. 본인의 이력서가 지원 가능한지 어떻게 판단했나요?</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>선배 대상:</span></span>
<span class="line"><span>1. 최근에 다른 사람의 이력서를 봐 준 것은 언제였나요?</span></span>
<span class="line"><span>2. 가장 자주 보이는 명확한 문제는 무엇인가요?</span></span>
<span class="line"><span>3. 후배들이 가장 쉽게 막히는 단계는 무엇인가요?</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>이렇게 하면 스스로 처음부터 질문을 만들 필요가 없어 인터뷰 준비가 훨씬 쉬워집니다.</p><h3 id="_12-3-ai에게-인터뷰-기록을-정리하게-하기" tabindex="-1">12.3 AI에게 인터뷰 기록을 정리하게 하기 <a class="header-anchor" href="#_12-3-ai에게-인터뷰-기록을-정리하게-하기" aria-label="Permalink to “12.3 AI에게 인터뷰 기록을 정리하게 하기”">​</a></h3><p>인터뷰를 마친 뒤 가장 흔한 문제는 &quot;정보가 없다&quot;가 아니라 &quot;정보가 너무 흩어져 있다&quot;입니다. AI는 조각난 대화를 구조화된 메모로 정리하는 데 매우 적합합니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>아래는 사용자 3명과의 인터뷰 기록이야.</span></span>
<span class="line"><span>The Mom Test 관점으로 정리해 줘.</span></span>
<span class="line"><span>1. 어떤 내용이 사실이고, 어떤 내용이 의견인가</span></span>
<span class="line"><span>2. 사용자의 최근 실제 행동은 무엇인가</span></span>
<span class="line"><span>3. 현재 대체 방안은 무엇인가</span></span>
<span class="line"><span>4. 사용자가 이미 지불한 시간, 돈, 에너지 비용은 무엇인가</span></span>
<span class="line"><span>5. 반복해서 언급된 문제는 무엇인가</span></span>
<span class="line"><span>6. 듣기에는 긍정적이지만 증거가 부족한 말은 무엇인가</span></span></code></pre></div><p>이 단계는 특히 가치가 있습니다. &quot;듣기에는 좋다&quot;와 &quot;판단을 뒷받침할 수 있다&quot;를 분리해 주기 때문입니다.</p><p>간단한 입력은 이렇게 쓸 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>한 사용자와 이야기한 기록이야.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 도구가 있으면 한번 써 볼 것 같다고 했다.</span></span>
<span class="line"><span>- 지난주 이력서를 고치느라 저녁 시간을 전부 썼다.</span></span>
<span class="line"><span>- 지금은 주로 친구에게 봐 달라고 한다.</span></span>
<span class="line"><span>- 가장 어려운 것은 어느 정도까지 고치면 지원해도 되는지 모른다는 점이라고 했다.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>어떤 것이 의견이고 어떤 것이 사실인지 나눠 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>의견:</span></span>
<span class="line"><span>- 도구가 있으면 한번 써 볼 것 같다고 했다.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>사실:</span></span>
<span class="line"><span>- 지난주 이력서를 고치느라 저녁 시간을 전부 썼다.</span></span>
<span class="line"><span>- 현재 대체 방안은 친구에게 봐 달라고 하는 것이다.</span></span>
<span class="line"><span>- 가장 어려운 점은 언제 &quot;지원 가능&quot;한 상태인지 모른다는 것이다.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>수요 판단에 쓸 수 있는 핵심:</span></span>
<span class="line"><span>- 이 문제는 최근에 실제로 발생했다.</span></span>
<span class="line"><span>- 사용자는 명확한 시간 비용을 이미 투입했다.</span></span>
<span class="line"><span>- 현재 방안은 다른 사람에게 의존하며 안정적이지 않다.</span></span></code></pre></div><p>이 출력은 초보자에게 어떤 말이 판단에 쓸 수 있고, 어떤 말은 그냥 들어 두는 정도인지 매우 직관적으로 알려 줍니다.</p><h3 id="_12-4-ai에게-먼저-가벼운-웹-검색을-시키기" tabindex="-1">12.4 AI에게 먼저 가벼운 웹 검색을 시키기 <a class="header-anchor" href="#_12-4-ai에게-먼저-가벼운-웹-검색을-시키기" aria-label="Permalink to “12.4 AI에게 먼저 가벼운 웹 검색을 시키기”">​</a></h3><p>아직 인터뷰를 시작하지 않았다면, AI에게 아주 가벼운 외부 조사를 맡길 수 있습니다.</p><ul><li>공개 커뮤니티에서 사람들이 최근 이 문제를 어떻게 불평하는지</li><li>기존 도구에서 가장 많이 불평받는 부분은 무엇인지</li><li>사용자가 유사한 문제에 이미 돈을 쓴 적이 있는지</li><li>시장에 어떤 대체 방안이 이미 존재하는지</li></ul><p>이 정보는 실제 사람 인터뷰를 대체할 수 없지만, 더 빨리 상태에 들어가고 문제를 어디서부터 파고들지 알게 해 줍니다.</p><p>간단한 입력 예시는 다음입니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>조사해 줘.</span></span>
<span class="line"><span>&quot;대학생이 이력서를 고칠 때 가장 자주 불평하는 것은 무엇인가&quot;</span></span>
<span class="line"><span>가장 흔한 불평 5개를 쉬운 말로 정리해 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>흔한 불평:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 이력서에 정확히 무엇을 써야 할지 모른다.</span></span>
<span class="line"><span>2. 직무 하나에 지원할 때마다 바꿔야 해서 너무 힘들다.</span></span>
<span class="line"><span>3. 여러 번 고쳤지만 좋은지 계속 확신이 없다.</span></span>
<span class="line"><span>4. 믿을 만한 피드백을 줄 사람이 없다.</span></span>
<span class="line"><span>5. 아직 준비가 안 된 것 같아 계속 미루게 된다.</span></span></code></pre></div><p>이 결과의 가치는 인터뷰 진입점을 더 쉽게 찾게 해 준다는 데 있습니다.</p><h3 id="_12-5-ai에게-인터뷰-회고-코치-역할을-맡기기" tabindex="-1">12.5 AI에게 &quot;인터뷰 회고 코치&quot; 역할을 맡기기 <a class="header-anchor" href="#_12-5-ai에게-인터뷰-회고-코치-역할을-맡기기" aria-label="Permalink to “12.5 AI에게 &quot;인터뷰 회고 코치&quot; 역할을 맡기기”">​</a></h3><p>방금 끝낸 인터뷰 기록을 AI에게 던져 비판하게 할 수도 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>아래는 내 사용자 인터뷰 기록이야.</span></span>
<span class="line"><span>The Mom Test 관점으로 회고해 줘.</span></span>
<span class="line"><span>1. 내 질문 중 어떤 것이 인정을 구하는 것처럼 들렸나</span></span>
<span class="line"><span>2. 어떤 질문이 명확하게 유도적이었나</span></span>
<span class="line"><span>3. 원래 사실을 더 캐물어야 했던 부분은 어디인가</span></span>
<span class="line"><span>4. 다시 한다면 이 대화를 어떻게 더 좋게 물어볼 수 있는가</span></span></code></pre></div><p>초보자에게 특히 도움이 됩니다. &quot;내가 증거를 모으고 있는지, 격려를 모으고 있는지&quot;에 대한 감각을 더 빨리 만들 수 있기 때문입니다.</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>위 내용을 바탕으로 다음 과제를 완료하세요.</p><ol><li>최근 만들고 싶은 제품 방향 하나를 고르고, 원래 물어봤을 &quot;망하기 쉬운&quot; 질문 5개를 먼저 쓰세요.</li><li>이 5개 질문을 The Mom Test 스타일에 더 맞는 질문으로 고쳐 쓰세요.</li><li>잠재 사용자 3명을 찾아 최소 한 번은 &quot;최근에 이 문제를 만난 것은 언제였나요?&quot;라고 물어보세요.</li><li>인터뷰 후 네 가지 정보를 정리하세요: 실제 행동, 대체 방안, 이미 지불한 비용, 반복해서 나타나는 어려움.</li></ol><h2 id="더-읽어-보기" tabindex="-1">더 읽어 보기 <a class="header-anchor" href="#더-읽어-보기" aria-label="Permalink to “더 읽어 보기”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test 공식 웹사이트</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,185))])}}});export{k as __pageData,m as default};
